def group_adjacent_states(grid):
    # Define the valid movements
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def get_adjacent_states(state):
        adjacent_states = []
        for movement in movements:
            new_state = grid[state // len(grid[0]) + movement[0]][state % len(grid[0]) + movement[1]]
            if 0 <= new_state < len(grid) * len(grid[0]):
                adjacent_states.append(new_state)
        return adjacent_states

    # Group the states
    grouped_states = {}

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            state = grid[i][j]
            if state != "X":
                adjacent_states = get_adjacent_states(j * len(grid) + i)

                if state not in grouped_states:
                    grouped_states[state] = []

                for adjacent_state in adjacent_states:
                    if adjacent_state not in grouped_states:
                        grouped_states[adjacent_state] = []

                    if adjacent_state not in [s for s in grouped_states[state]]:
                        grouped_states[state].append(adjacent_state)
                    if state not in [s for s in grouped_states[adjacent_state]]:
                        grouped_states[adjacent_state].append(state)

    return list(grouped_states.keys())

