def get_valid_states(state):
    x, y = state
    valid_states = []

    # check if adjacent cell is within grid boundaries and not an obstacle
    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        new_x, new_y = x + dx, y + dy

        # Check if the new state is inside the grid and is not an obstacle.
        if 0 <= new_x < len(grid[0]) and 0 <= new_y < len(grid) and grid[new_y][new_x] != 'X':
            valid_states.append((new_x, new_y))

    return valid_states

def group_states_by_abstraction(start_state):
    # Define a dictionary to store the groups of states
    state_groups = {start_state: [start_state]}

    # Use BFS to expand all reachable states and group them
    queue = [start_state]
    while queue:
        current_state = queue.pop(0)

        for next_state in get_valid_states(current_state):
            if next_state not in state_groups:
                state_groups[start_state].append(next_state)
                queue.append(next_state)

    return list(state_groups.values())

